#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    // No arguments provided
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end1, *end2;
    long mode = strtol(argv[1], &end1, 10);
    long n = strtol(argv[2], &end2, 10);

    // Ensure full conversion of both arguments
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    // Second argument must be non‑negative and not exceed the limit used by the original binary
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    double sum = 0.0;

    switch (mode) {
        case 1: // sum of 1/(i*i)
            for (long i = 1; i <= n; ++i) {
                sum += 1.0 / ((double)i * (double)i);
            }
            break;
        case 2: // harmonic series 1/i
            for (long i = 1; i <= n; ++i) {
                sum += 1.0 / (double)i;
            }
            break;
        case 3: { // partial sum of e = Σ 1/i!
            double term = 1.0; // 1/0!
            sum = term;
            for (long i = 1; i <= n; ++i) {
                term /= (double)i; // term = 1/i!
                sum += term;
            }
            break;
        }
        default:
            puts("BAD_MODE");
            return 0;
    }

    printf("%.6f\n", sum);
    return 0;
}
